<fieldset class="question"><legend>Question <?= (int)$index+1 ?></legend><input type="hidden" name="questions[<?= e($key) ?>][id]" value="<?= e($key) ?>"><label for="label_<?= e($key) ?>">Question label (leave blank to skip)</label><input id="label_<?= e($key) ?>" name="questions[<?= e($key) ?>][label]" maxlength="120" value="<?= e($question['label']??'') ?>"><label for="type_<?= e($key) ?>">Field type</label><select id="type_<?= e($key) ?>" name="questions[<?= e($key) ?>][type]"><?php foreach(['text'=>'Short text','textarea'=>'Long text','select'=>'Selection','checkbox'=>'Checkbox','url'=>'Portfolio / audition link','file'=>'Private attachment'] as $type=>$label):?><option value="<?= e($type) ?>"<?= ($question['type']??'text')===$type?' selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select><label for="order_<?= e($key) ?>">Order</label><input id="order_<?= e($key) ?>" name="questions[<?= e($key) ?>][order]" type="number" min="0" max="999" value="<?= (int)($question['order']??($index+1)*10) ?>"><label for="options_<?= e($key) ?>">Selection choices (one per line; selection fields only)</label><textarea id="options_<?= e($key) ?>" name="questions[<?= e($key) ?>][options]" rows="3"><?= e(implode("\n",$question['options']??[])) ?></textarea><label class="check"><input type="checkbox" name="questions[<?= e($key) ?>][required]" value="1"<?= !empty($question['required'])?' checked':'' ?>> Required answer</label><label class="check"><input type="checkbox" name="questions[<?= e($key) ?>][remove]" value="1"> Remove this question when saving</label></fieldset>
